import gurobipy as gp
from gurobipy import GRB

env = gp.Env(empty=True)
env.setParam('LogFile', 'gurobi.log')
env.start()

model = gp.Model(env=env)

R = [10, 15, 25, 20, 18, 12]
x = model.addVars(6, vtype=GRB.INTEGER, name='x')

for t in range(6):
    if t == 0:
        model.addConstr(x[0] + x[5] >= R[t])
    elif t == 1:
        model.addConstr(x[0] + x[1] >= R[t])
    elif t == 2:
        model.addConstr(x[1] + x[2] >= R[t])
    elif t == 3:
        model.addConstr(x[2] + x[3] >= R[t])
    elif t == 4:
        model.addConstr(x[3] + x[4] >= R[t])
    else:
        model.addConstr(x[4] + x[5] >= R[t])

model.setObjective(sum(x), GRB.MINIMIZE)

model.optimize()

if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")

import gurobipy as gp
from gurobipy import GRB

# Read the time matrix
t = [
    [3, 1, 1],
    [2, 1.5, 1],
    [3, 1.2, 1.3],
    [2, 2, 2],
    [2.1, 2, 3]
]

# Create the model
env = gp.Env(empty=True)
env.setParam('OutputFlag', False)
model = gp.Model(env=env)

# Decision variables
S = []
for i in range(5):
    S_i = []
    for j in range(3):
        var = model.addVar(name=f'S_{i}_{j}', vtype=GRB.CONTINUOUS, lb=0)
        S_i.append(var)
    S.append(S_i)

# Binary variables y[i][k][j]
y = [[[None for _ in range(5)] for _ in range(5)] for _ in range(3)]
for j in range(3):
    for i in range(5):
        for k in range(5):
            if i != k:
                y[j][i][k] = model.addVar(name=f'y_{i}_{k}_{j}', vtype=GRB.BINARY)

# Sequence constraints
for i in range(5):
    model.addConstr(S[i][1] >= S[i][0] + t[i][0])
    model.addConstr(S[i][2] >= S[i][1] + t[i][1])

# Non-overlapping constraints
M = 30  # Total processing time is 28.1, so M=30 is sufficient
for j in range(3):
    for i in range(5):
        for k in range(5):
            if i != k:
                model.addConstr(S[i][j] + t[i][j] <= S[k][j] + M * (1 - y[j][i][k]))
                model.addConstr(S[k][j] + t[k][j] <= S[i][j] + M * y[j][i][k])

# Objective
C = model.addVar(vtype=GRB.CONTINUOUS, name='C')
for i in range(5):
    model.addConstr(C >= S[i][2] + t[i][2])
model.setObjective(C, GRB.MINIMIZE)

# Optimize
model.optimize()

# Check if optimal
if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={C.x}")
else:
    print("No optimal solution found.")

import gurobipy as gp
from gurobipy import GRB

# Initialize environment and model
env = gp.Env(empty=True)
model = gp.Model(env=env)

# Parameters
h = {
    'A': {'I': 8, 'II': 2, 'III': 10},
    'B': {'I': 10, 'II': 5, 'III': 8},
    'C': {'I': 2, 'II': 13, 'III': 10}
}
H = {'A': 300, 'B': 400, 'C': 420}
P = {'I': 3, 'II': 2, 'III': 2.9}

# Decision variables
products = ['I', 'II', 'III']
x = {}
for p in products:
    x[p] = model.addVar(vtype=GRB.CONTINUOUS, name=f'x_{p}')

# Objective: Maximize total profit
model.setObjective(sum(P[p] * x[p] for p in products), GRB.MAXIMIZE)

# Constraints: Equipment capacity limits
for e in ['A', 'B', 'C']:
    expr = sum(h[e][p] * x[p] for p in products)
    model.addConstr(expr <= H[e], f'Capacity_{e}')

# Optimize
model.optimize()

# Output final objective value if optimal
if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")

