from gurobipy import GRB

# Distance matrix for cities 1 to 7
D = [
    [0, 86, 49, 57, 31, 69, 50],
    [86, 0, 68, 79, 93, 24, 5],
    [49, 68, 0, 16, 7, 72, 67],
    [57, 79, 16, 0, 90, 69, 1],
    [31, 93, 7, 90, 0, 86, 59],
    [69, 24, 72, 69, 86, 0, 81],
    [50, 5, 67, 1, 59, 81, 0]
]

# Create model
env = gp.Env(empty=True)
env.setParam('LogFile', 'tsp.log')
model = gp.Model(env=env)

# Decision variables
x = {}
for i in range(1, 8):
    for j in range(1, 8):
        if i != j:
            x[(i, j)] = model.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}")

# Objective function
obj_expr = gp.LinExpr()
for i in range(1, 8):
    for j in range(1, 8):
        if i != j:
            obj_expr += D[i-1][j-1] * x[(i, j)]
model.setObjective(obj_expr, GRB.MINIMIZE)

# Constraints: each city has exactly one outgoing edge
for i in range(1, 8):
    out_expr = gp.LinExpr()
    for j in range(1, 8):
        if i != j:
            out_expr += x[(i, j)]
    model.addConstr(out_expr == 1, f"out_{i}")

# Constraints: each city has exactly one incoming edge
for i in range(1, 8):
    in_expr = gp.LinExpr()
    for j in range(1, 8):
        if i != j:
            in_expr += x[(j, i)]
    model.addConstr(in_expr == 1, f"in_{i}")

# Optimize
model.optimize()

# Check if optimal and print the objective value
if model.status == GRB.OPTIMAL:
