model = gp.Model(env=env)

# Create variables for x_{i,j}
x = {}
for workshop in ['A', 'B', 'C', 'D']:
    x[workshop] = {}
    for component in [1, 2, 3]:
        x[workshop][component] = model.addVar(lb=0, vtype=GRB.CONTINUOUS, name=f"x_{workshop}_{component}")

Z = model.addVar(lb=0, vtype=GRB.CONTINUOUS, name="Z")

# Add workshop capacity constraints
capacities = {'A': 100, 'B': 150, 'C': 80, 'D': 200}
for workshop in capacities:
    capacity = capacities[workshop]
    expr = gp.quicksum(x[workshop][j] for j in [1, 2, 3])
    model.addConstr(expr <= capacity, f"Capacity_{workshop}")

# Add component constraints
for j in [1, 2, 3]:
    if j == 1:
        rates = [10, 15, 20, 10]
    elif j == 2:
        rates = [15, 10, 5, 15]
    else:
        rates = [5, 5, 10, 20]
    expr = 0
    for i in range(4):
        workshop = ['A', 'B', 'C', 'D'][i]
        expr += rates[i] * x[workshop][j]
    model.addConstr(expr >= Z, f"Component_{j}_constraint")

# Set objective to maximize Z
model.setObjective(Z, GRB.MAXIMIZE)

model.optimize()

if model.Status == GRB.OPTIMAL:
