import gurobipy as gp
from gurobipy import GRB

model = gp.Model(env=env)
shifts = [2, 6, 10, 14, 18, 22]
required = {2: 10, 6: 15, 10: 25, 14: 20, 18: 18, 22: 12}

r_vars = {}
c_vars = {}
for s in shifts:
    r = model.addVar(lb=0, vtype=GRB.INTEGER, name=f"r_{s}")
    c = model.addVar(lb=0, vtype=GRB.INTEGER, name=f"c_{s}")
    r_vars[s] = r
    c_vars[s] = c

covering_shifts = {
    2: [2, 22],
    6: [2, 6],
    10: [6, 10],
    14: [10, 14],
    18: [14, 18],
    22: [18, 22]
}

for t in required:
    covering = covering_shifts[t]
    expr = 0
    for s in covering:
        expr += r_vars[s] + c_vars[s]
    model.addConstr(expr >= required[t], f"constraint_{t}")

obj_expr = 0
for s in shifts:
    obj_expr += 80 * r_vars[s] + 120 * c_vars[s]
model.setObjective(obj_expr, GRB.MINIMIZE)

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")

